G=load()
def f(g):
    bg=g[0][0]; H,W=len(g),len(g[0])
    pos={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: pos.setdefault(g[r][c],[]).append((r,c))
    out=[row[:] for row in g]
    D=[(1,1),(1,-1),(-1,1),(-1,-1)]
    for col,cs in sorted(pos.items()):
        cs=sorted(cs,key=lambda p:p[0])
        if len(cs)<2:
            # singleton: rays in all 4 diag dirs, painting bg until edge or non-bg (use original grid for block check)
            for u,v in D:
                rr,cc=cs[0]+u,cs[0][1]+v
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    out[rr][cc]=col; rr+=u; cc+=v
            continue
        # >=2: draw segment from first to last seed along the diagonal, painting bg only, skipping occupied cells
        dr,dc=cs[-1]-cs[0]
        u,v=dr//gcd(abs(dr),abs(dc)), dc//gcd(abs(dr),abs(dc))
        for i in range(1,len(cs)):
            a,b=cs[i-1],cs[i]
            rr,cc=a[0]+u,a[1]+v
            # walk from just after a up to b, painting bg only, never painting non-bg
            while (rr,cc)!=(a[0]+i*u,a[1]+i*v) and out[rr][cc]==bg:
                out[rr][cc]=col; rr+=u; cc+=v
    return out
